import React from 'react';
import { Link } from 'react-router-dom';

function Header() {
  return (
    <header>
      <h1>eStore Admin</h1>
      <nav>
        <Link to="/admin/products">Product List</Link>
        <Link to="/admin/add-product">Add Product</Link>
      </nav>
    </header>
  );
}

export default Header;
